class Functions:
    def __init__(self):
        # 注意：Ui_Video_to_Audio 不应该在这里实例化，因为它属于 GUI 层
        # self.ui = Ui_Video_to_Audio() # 错误：不要在这里创建 UI 实例
        self.input_folder = ""
        self.output_folder = ""
        self.expect_style = ""
        # 假设你有办法获取文件列表，这里先留空
        self.VideoLis = []
        self.VideoFormatLis = []

    def VtA(self):
        """执行视频到音频的转换。"""
        # 在实际应用中，你需要先获取输入目录下的视频文件列表
        # 这里假设 VideoLis 和 VideoFormatLis 已经被正确填充
        if not self.VideoLis:
            print("错误：没有找到要转换的视频文件。")
            return

        for i in range(len(self.VideoLis)):
            video_name = self.VideoLis[i]
            ext = self.VideoFormatLis[i]
            input_path = os.path.join(self.input_folder, video_name + ext)

            # 检查输入文件是否存在
            if not os.path.exists(input_path):
                print(f"警告：输入文件不存在，跳过: {input_path}")
                continue

            try:
                stat_info_input = os.stat(input_path)
                file_size_bytes_input = stat_info_input.st_size / 1024 / 1024
                print(f"输入文件大小: {file_size_bytes_input:.2f} MB")

                # 决定输出格式
                # 优先使用用户指定的格式，如果无效或为空，则根据文件大小判断
                output_ext = self.expect_style.lower()
                if output_ext not in [".mp3", ".wav"]:
                    print(f"指定的格式 '{output_ext}' 无效或为空，根据文件大小决定。")
                    if file_size_bytes_input <= 512.00:
                        output_ext = ".wav"
                    else:
                        output_ext = ".mp3"

                output_path = os.path.join(self.output_folder, video_name + output_ext)

                # 执行转换 (调用你的实际转换函数)
                Convert(InputPath=input_path, OutputPath=output_path)

                # 检查输出文件
                if os.path.exists(output_path):
                    stat_info_output = os.stat(output_path)
                    file_size_bytes_output = stat_info_output.st_size / 1024 / 1024
                    print(f"输出文件大小: {file_size_bytes_output:.2f} MB")
                    ysl = (1 - file_size_bytes_output / file_size_bytes_input) * 100
                    print(f"压缩率: {ysl:.2f}%")
                else:
                    print(f"错误：转换后未找到输出文件: {output_path}")

            except Exception as e:
                print(f"处理文件 {input_path} 时出错: {e}")

            print("-" * 40)


class MainWindow(QtWidgets.QMainWindow):
    """主窗口类，负责整合 UI 和业务逻辑。"""

    def __init__(self):
        super().__init__()
        self.ui = Ui_Video_to_Audio()  # 创建 UI 实例
        self.ui.setupUi(self)  # 设置 UI
        self.functions = Functions()  # 创建业务逻辑实例
        self.setup_connections()  # 连接信号和槽

    def setup_connections(self):
        """连接 UI 信号到槽函数。"""
        # 将按钮的 clicked 信号连接到 on_convert_button_clicked 方法
        self.ui.pushButton.clicked.connect(self.on_convert_button_clicked)

    def on_convert_button_clicked(self):
        """按钮点击时执行的槽函数。"""
        # 获取用户输入
        input_path = self.ui.lineEdit.text().strip()
        output_path = self.ui.lineEdit_2.text().strip()
        expect_style = self.ui.lineEdit_4.text().strip()

        # 输入验证
        if not input_path:
            QtWidgets.QMessageBox.warning(self, "输入错误", "请输入输入路径！")
            return
        if not output_path:
            QtWidgets.QMessageBox.warning(self, "输入错误", "请输入输出路径！")
            return
        if expect_style and expect_style.lower() not in [".mp3", ".wav"]:
            QtWidgets.QMessageBox.warning(self, "输入错误", f"期望格式 '{expect_style}' 无效。请使用 .mp3 或 .wav")
            return

        # 验证输入路径是否存在
        if not os.path.exists(input_path):
            QtWidgets.QMessageBox.warning(self, "路径错误", f"输入路径不存在:\n{input_path}")
            return

        # 尝试创建输出目录
        try:
            os.makedirs(output_path, exist_ok=True)
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "创建目录失败", f"无法创建输出目录:\n{output_path}\n错误: {e}")
            return

        # 更新 Functions 实例的参数
        self.functions.input_folder = input_path
        self.functions.output_folder = output_path
        self.functions.expect_style = expect_style

        # --- 关键：获取输入目录下的视频文件 ---
        # 这是一个简单的实现，只查找特定扩展名的文件
        video_extensions = (".mp4", ".avi", ".mkv", ".mov", ".wmv", ".flv")  # 添加你需要的扩展名
        try:
            files = os.listdir(input_path)
            self.functions.VideoLis = []
            self.functions.VideoFormatLis = []
            for file in files:
                if file.lower().endswith(video_extensions):
                    # 分离文件名和扩展名
                    name, ext = os.path.splitext(file)
                    self.functions.VideoLis.append(name)
                    self.functions.VideoFormatLis.append(ext)
            if not self.functions.VideoLis:
                QtWidgets.QMessageBox.information(self, "信息", "在指定输入路径中未找到支持的视频文件。")
                return
            print(f"找到 {len(self.functions.VideoLis)} 个视频文件准备转换。")

        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "读取目录失败", f"无法读取输入目录:\n{input_path}\n错误: {e}")
            return

        # 执行转换
        try:
            print("开始转换...")
            self.functions.VtA()
            QtWidgets.QMessageBox.information(self, "完成", "所有文件转换完成！")
        except Exception as e:
            QtWidgets.QMessageBox.critical(self, "转换失败", f"转换过程中发生错误:\n{e}")


if __name__ == "__main__":
    app = QtWidgets.QApplication(sys.argv)
    window = MainWindow()
